package com.ivonix.pulse.ontology.academy;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.ivonix.pulse.ontology.eventbus.EventBusService; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AcademyService{
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final EventBusService bus;private final CertificateSigner signer;private final CertificateRenderClient renderer;public AcademyService(JdbcTemplate j,ObjectMapper m,EventBusService b,CertificateSigner s,CertificateRenderClient r){jdbc=j;mapper=m;bus=b;signer=s;renderer=r;}
 private void member(UUID org,UUID user){Integer n=jdbc.queryForObject("select count(*) from public.organization_members where organization_id=? and user_id=?",Integer.class,org,user);if(n==null||n<1)throw new SecurityException("Organization membership required");}
 public List<Map<String,Object>> courses(UUID org,UUID user){member(org,user);return jdbc.queryForList("select * from public.academy_courses where organization_id=? and published=true order by title",org);}
 public UUID enroll(UUID org,UUID course,UUID user){member(org,user);Boolean ok=jdbc.queryForObject("select published from public.academy_courses where id=? and organization_id=?",Boolean.class,course,org);if(!Boolean.TRUE.equals(ok))throw new IllegalArgumentException("Course not published");return jdbc.queryForObject("insert into public.academy_enrollments(course_id,user_id) values(?,?) on conflict(course_id,user_id) do update set enrolled_at=academy_enrollments.enrolled_at returning id",UUID.class,course,user);}
 public void completeLesson(UUID org,UUID enrollment,UUID lesson,UUID user,int seconds){member(org,user);if(seconds<0||seconds>86400)throw new IllegalArgumentException("Invalid time spent");Integer owned=jdbc.queryForObject("select count(*) from public.academy_enrollments e join public.academy_courses c on c.id=e.course_id join public.academy_lessons l on l.module_id in(select id from public.academy_modules where course_id=c.id) where e.id=? and e.user_id=? and l.id=?",Integer.class,enrollment,user,lesson);if(owned==null||owned!=1)throw new SecurityException("Lesson not in enrollment");jdbc.update("insert into public.academy_lesson_progress(enrollment_id,lesson_id,time_spent_seconds) values(?,?,?) on conflict(enrollment_id,lesson_id) do update set time_spent_seconds=greatest(academy_lesson_progress.time_spent_seconds,excluded.time_spent_seconds),completed_at=coalesce(academy_lesson_progress.completed_at,now())",enrollment,lesson,seconds);recalc(enrollment);}
 private void recalc(UUID e){Map<String,Object> r=jdbc.queryForMap("with t as(select count(*) n from public.academy_lessons l join public.academy_modules m on m.id=l.module_id where m.course_id=(select course_id from public.academy_enrollments where id=?)),d as(select count(*) n from public.academy_lesson_progress where enrollment_id=?) select case when t.n=0 then 0 else round(100.0*d.n/t.n,2) end pct from t,d",e,e);double p=((Number)r.get("pct")).doubleValue();jdbc.update("update public.academy_enrollments set progress_percent=?,completed_at=case when ?=100 then coalesce(completed_at,now()) else completed_at end where id=?",p,p,e);}
 public Map<String,Object> submitQuiz(UUID org,UUID quiz,UUID user,List<Object> answers){member(org,user);Map<String,Object> q=jdbc.queryForMap("select id,course_id,pass_score,questions from public.academy_quizzes where id=?",quiz);Integer inCourse=jdbc.queryForObject("select count(*) from public.academy_enrollments e where e.course_id=? and e.user_id=?",Integer.class,q.get("course_id"),user);if(inCourse==null||inCourse!=1)throw new SecurityException("Enrollment required");List<Map<String,Object>> qs=mapper.convertValue(q.get("questions"),new TypeReference<List<Map<String,Object>>>(){});if(answers==null||answers.size()>qs.size())throw new IllegalArgumentException("Invalid answer count");int correct=0;List<Boolean> results=new ArrayList<>();for(int i=0;i<qs.size();i++){Object expected=qs.get(i).get("answer");Object given=i<answers.size()?answers.get(i):null;boolean same=Objects.equals(normalize(expected),normalize(given));results.add(same);if(same)correct++;}double score=qs.isEmpty()?0:100.0*correct/qs.size();boolean passed=score>=((Number)q.get("pass_score")).doubleValue();Integer attempt=jdbc.queryForObject("select coalesce(max(attempt_number),0)+1 from public.academy_quiz_attempts where quiz_id=? and user_id=?",Integer.class,quiz,user);try{jdbc.update("insert into public.academy_quiz_attempts(quiz_id,user_id,score,passed,answers,attempt_number) values(?,?,?,?,?::jsonb,?)",quiz,user,score,passed,mapper.writeValueAsString(Map.of("given",answers,"results",results)),attempt);}catch(Exception ex){throw new IllegalStateException("Quiz attempt could not be persisted",ex);}return Map.of("score",score,"passed",passed,"results",results,"attemptNumber",attempt);}
 private Object normalize(Object x){if(x instanceof Collection<?> c)return new HashSet<>(c);return x;}
 public UUID issueCertificate(UUID org,UUID course,UUID user){member(org,user);Integer complete=jdbc.queryForObject("select count(*) from public.academy_lesson_progress p join public.academy_enrollments e on e.id=p.enrollment_id where e.course_id=? and e.user_id=?",Integer.class,course,user);Integer total=jdbc.queryForObject("select count(*) from public.academy_lessons l join public.academy_modules m on m.id=l.module_id where m.course_id=?",Integer.class,course);if(complete==null||total==null||complete<total)throw new IllegalStateException("Course not complete");Integer missing=jdbc.queryForObject("select count(*) from public.academy_quizzes q where q.course_id=? and not exists(select 1 from public.academy_quiz_attempts a where a.quiz_id=q.id and a.user_id=? and a.passed=true)",Integer.class,course,user);if(missing!=null&&missing>0)throw new IllegalStateException("Quiz requirements not met");try{UUID existing=jdbc.queryForObject("select id from public.academy_certificates where course_id=? and user_id=? and revoked=false",UUID.class,course,user);if(existing!=null)return existing;}catch(Exception ignored){}
 String title=jdbc.queryForObject("select title from public.academy_courses where id=? and organization_id=?",String.class,course,org);String userName=jdbc.queryForObject("select coalesce(raw_user_meta_data->>'full_name',email) from auth.users where id=?",String.class,user);String number="PLS-"+course.toString().substring(0,8).toUpperCase(Locale.ROOT)+"-"+user.toString().substring(0,8).toUpperCase(Locale.ROOT)+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);UUID id=UUID.randomUUID();String payload=id+"|"+number+"|"+course+"|"+user;String sig=signer.sign(payload);String path="certificates/"+org+"/"+id+".pdf";jdbc.update("insert into public.academy_certificates(id,course_id,user_id,certificate_number,expires_at,signature,public_key,verification_payload,pdf_path) values(?,?,?,?,now()+interval '3 years',?,?,?,?,?)",id,course,user,number,sig,signer.publicKey(),payload,path);renderer.render(id,title,userName==null?user.toString():userName,number,sig,java.time.Instant.now().toString(),path);bus.publish("academy.certificate_issued","pulse-academy",Map.of("certificateId",id,"courseId",course,"userId",user,"certificateNumber",number),org,id.toString());return id;}
}